  ).get(orgId, projectId) as { last_number: number } | undefined;
  return Math.max(row?.value ?? 0, counter?.last_number ?? 0);
}

function rememberIssueNumber(orgId: OrgId, projectId: ProjectId, number: number): void {
  getDb().$client.prepare(`
    INSERT INTO issue_number_counters (org_id, project_id, last_number) VALUES (?, ?, ?)
    ON CONFLICT (org_id, project_id) DO UPDATE SET last_number = max(last_number, excluded.last_number)
  `).run(orgId, projectId, number);
}

export async function nextIssueNumber(orgId: OrgId, projectId: ProjectId): Promise<number> {
  return highestIssueNumber(orgId, projectId) + 1;
}

